public class CreatorCollector_verifyNonDup_TriageGen1Test {

    private CreatorCollector creatorCollector;
    private BeanDescription beanDesc;
    private AnnotatedWithParams mockNewOne;
    private AnnotatedWithParams mockOldOne;

    // Accessing protected fields via reflection for testing purposes
    private static final String CREATORS_FIELD = "_creators";
    private static final String EXPLICIT_CREATORS_FIELD = "_explicitCreators";
    private static final String HAS_NON_DEFAULT_CREATOR_FIELD = "_hasNonDefaultCreator";

    @Before
    public void setUp() throws Exception {
        beanDesc = mock(BeanDescription.class);
        creatorCollector = new CreatorCollector(beanDesc, true);
        mockNewOne = mock(AnnotatedWithParams.class);
        mockOldOne = mock(AnnotatedWithParams.class);

        // Ensure mockNewOne returns itself for _fixAccess simulation if needed, 
        // but here we focus on the logic of verifyNonDup.
    }

    /**
     * Helper to set the private _creators array via reflection
     */
    private void setCreatorsArray(AnnotatedWithParams[] creators) throws Exception {
        Field field = CreatorCollector.class.getDeclaredField(CREATORS_FIELD);
        field.setAccessible(true);
        field.set(creatorCollector, creators);
    }

    /**
     * Helper to get the private _creators array via reflection
     */
    private AnnotatedWithParams[] getCreatorsArray() throws Exception {
        Field field = CreatorCollector.class.getDeclaredField(CREATORS_FIELD);
        field.setAccessible(true);
        return (AnnotatedWithParams[]) field.get(creatorCollector);
    }

    /**
     * Helper to get the private _explicitCreators bitmask
     */
    private long getExplicitCreators() throws Exception {
        Field field = CreatorCollector.class.getDeclaredField(EXPLICIT_CREATORS_FIELD);
        field.setAccessible(true);
        return (long) field.get(creatorCollector);
    }

    /**
     * Helper to set the private _explicitCreators bitmask
     */
    private void setExplicitCreators(long value) throws Exception {
        Field field = CreatorCollector.class.getDeclaredField(EXPLICIT_CREATORS_FIELD);
        field.setAccessible(true);
        field.set(creatorCollector, value);
    }

    @Test
    public void testVerifyNonDup_FirstTime() throws Exception {
        int typeIndex = 0;
        setCreatorsArray(new AnnotatedWithParams[10]);

        // Invoke protected method via reflection
        invokeVerifyNonDup(mockNewOne, typeIndex, false);

        assertTrue("Should set _hasNonDefaultCreator to true", creatorCollector.hasDefaultCreator());
        assertEquals("Should store the new creator", mockNewOne, getCreatorsArray()[typeIndex]);
    }

    @Test
    public void testVerifyNonDup_FirstTimeExplicit() throws Exception {
        int typeIndex = 1;
        setCreatorsArray(new AnnotatedWithParams[10]);

        invokeVerifyNonDup(mockNewOne, typeIndex, true);

        assertTrue(creatorCollector.hasDefaultCreator());
        assertEquals(mockNewOne, getCreatorsArray()[typeIndex]);
        assertEquals("Explicit mask should be set", (1L << typeIndex), getExplicitCreators());
    }

    @Test
    public void testVerifyNonDup_AlreadyHasExplicit_NewIsNotExplicit_ReturnEarly() throws Exception {
        int typeIndex = 0;
        setCreatorsArray(new AnnotatedWithParams[]{mockOldOne});
        setExplicitCreators(1L << typeIndex); // Already had explicit

        // newOne is NOT explicit
        invokeVerifyNonDup(mockNewOne, typeIndex, false);

        // Should return early without updating _creators or mask
        assertEquals(mockOldOne, getCreatorsArray()[typeIndex]);
        assertEquals(1L << typeIndex, getExplicitCreators());
    }

    @Test
    public void testVerifyNonDup_AlreadyHasExplicit_NewIsExplicit_ProceedToVerify() throws Exception {
        int typeIndex = 0;
        setCreatorsArray(new AnnotatedWithParams[]{mockOldOne});
        setExplicitCreators(1L << typeIndex);

        // newOne IS explicit. It should skip the 'return' and proceed to class comparison.
        // We use different classes to avoid IllegalArgumentException
        AnnotatedWithParams differentClassNewOne = mock(AnnotatedWithParams.class);
        // Assuming AnnotatedWithParams is a class, mock returns a proxy of the same class.
        // To trigger the exception, they must be the same class. To pass, they must be different.
        // Since we can't easily mock a different class for the same type, 
        // we verify the logic flows to the comparison.

        // If we want to test the "both explicit" logic block:
        // The code says: if (oldOne.getClass() == newOne.getClass()) throw ...
        // If we use the same mock, it will throw.
        try {
            invokeVerifyNonDup(mockNewOne, typeIndex, true);
            fail("Should have thrown IllegalArgumentException because classes match");
        } catch (Exception e) {
            assertTrue(e.getCause() instanceof IllegalArgumentException);
        }
    }

    @Test(expected = Exception.class) // Wrapper exception for reflection
    public void testVerifyNonDup_ConflictSameClass() throws Exception {
        int typeIndex = 0;
        setCreatorsArray(new AnnotatedWithParams[]{mockOldOne});
        // No explicit bit set
        setExplicitCreators(0L);

        // Both have same class (mock objects)
        invokeVerifyNonDup(mockNewOne, typeIndex, false);
    }

